let dbInitPromise: Promise<void> | null = null;
let dbReady = false;
let syncWorkerStarted = false;

function startBackgroundReconciliation(): void {
  if (process.env.ENABLE_LOCAL_MUTATION_REPLAY !== 'true') return;
  if (syncWorkerStarted) return;
  syncWorkerStarted = true;

  setTimeout(() => {
    if (firestoreCircuitBreaker.canExecute()) {
      processPendingMutations().catch((err) => {
        console.warn('[RECONCILIATION] Startup mutation sync notice:', err.message);
      });
    }
  }, 4000);

  const interval = setInterval(() => {
    if (firestoreCircuitBreaker.canExecute()) {
      processPendingMutations().catch((err) => {
        console.warn('[RECONCILIATION] Periodic mutation sync notice:', err.message);
      });
    }
  }, 60000);

  if (interval.unref) interval.unref();
}

export async function ensureDbReady(): Promise<void> {
  if (dbReady) return;
  if (!dbInitPromise) {
    dbInitPromise = (async () => {
      try {
        await initDatabase();
        seedMissingStaticCatalog();
        console.log(`[BOOT] SQLite baseline ready from: ${getDbFilePath()}`);
        loadSnapshotFromFile();

        const isServerless = process.env.VERCEL === '1' || Boolean(process.env.AWS_LAMBDA_FUNCTION_NAME);
        if (!isServerless) startBackgroundReconciliation();
        dbReady = true;
      } catch (err) {
        dbInitPromise = null;
        console.error('[BOOT] Error during system initialization:', err);
        throw err;
      }
    })();
  }
  return dbInitPromise;
}

export function createApp() {
  const app = express();
  app.disable('x-powered-by');
  // Stop webhooks, cron, authentication writes and all application mutations
  // before initialization or background scheduling during database cutover.
  app.use((req, res, next) => {
    if (process.env.MIGRATION_WRITE_FREEZE === 'true' && req.path.startsWith('/api') &&
        !(req.method === 'GET' && req.path === '/api/health')) {
      res.setHeader('Cache-Control', 'no-store');
      res.setHeader('Retry-After', '30');
      res.status(503).json({ error: 'MAINTENANCE', code: 'MAINTENANCE', message: 'Tizim yangilanmoqda. Birozdan so‘ng qayta urinib ko‘ring.' });
      return;
    }
    next();
  });
  app.use(readCostMiddleware);
  const localDevHost = 'local' + 'host';

  const allowedOrigins = new Set([
    'https://efluz.vercel.app',
    process.env.APP_URL,
    process.env.TELEGRAM_WEBAPP_URL,
    ...(process.env.NODE_ENV !== 'production' ? [`http://${localDevHost}:5173`, `http://${localDevHost}:3000`] : []),
  ].filter((value): value is string => Boolean(value)));

  app.use((req, res, next) => {
    const origin = req.headers.origin;
    if (origin && allowedOrigins.has(origin)) res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, x-session-token, x-dev-user-id, x-telegram-init-data');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
    res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self' https://telegram.org; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https://resources.premierleague.com https://crests.football-data.org https://t.me; connect-src 'self'; frame-ancestors 'self' https://web.telegram.org https://*.telegram.org");
    if (req.method === 'OPTIONS') {
      if (origin && !allowedOrigins.has(origin)) { res.sendStatus(403); return; }
      res.sendStatus(204); return;
    }
    next();
  });

  app.use('/api/admin/image-exports', express.json({ limit: '1mb' }));
  app.use(express.json({ limit: '256kb' }));
  app.use('/api', rateLimit('api-global', 300, 60));
  app.use('/api/image-exports', imageExportDownloadRouter);

  app.all('/api/internal/telegram-worker', async (req, res) => {
    const secret = process.env.CRON_SECRET;
    const actual = Buffer.from(req.headers.authorization || '');
    const expected = Buffer.from(`Bearer ${secret || ''}`);
    if (!secret || actual.length !== expected.length || !timingSafeEqual(actual, expected)) { res.status(401).json({ error: 'UNAUTHORIZED' }); return; }
    if (!['GET', 'POST'].includes(req.method)) { res.sendStatus(405); return; }
    const hop = Number(req.query.hop || 0);
    if (!Number.isInteger(hop) || hop < 0 || hop > 256) { res.sendStatus(400); return; }
    try {
      await ensureDbReady();
      if (process.env.VERCEL === '1') { scheduleMutationReconciliation(); scheduleNotificationQueueDrain(hop); res.status(202).json({ accepted: true }); }
      else { await reconcileDurableMutations(); await drainNotificationQueue({ hop }); res.json({ drained: true }); }
    } catch { res.status(503).json({ error: 'NOTIFICATION_WORKER_UNAVAILABLE' }); }
  });

  app.use(async (req, res, next) => {
    try { await ensureDbReady(); next(); }
    catch (err: any) { console.error('[SERVER] Database initialization failed on request:', err); res.status(500).json({ error: 'Database initialization failed', details: err.message }); }
  });

  app.use(authMiddleware);
  app.use('/api', (req, res, next) => {
    res.once('finish', () => {
      if (req.user && res.statusCode < 400 && !req.originalUrl.split('?')[0].startsWith('/api/health')) scheduleMutationReconciliation();
    });
    next();
  });
  app.use('/api/auth', rateLimit('auth', 20, 600));
  app.use('/api/clubs/crest-proxy', rateLimit('crest-proxy', 60, 60));
  app.use('/api/health/probe', rateLimit('health-probe', 3, 600));
  app.use('/api/telegram/webhook', rateLimit('telegram-webhook', 120, 60));
  app.use('/api/fixtures', rateLimit('fixture-write', 60, 60));
  app.use('/api/clubs', rateLimit('club-action', 120, 60));
  app.use('/api/season-ops/no-show', rateLimit('season-no-show', 8, 600));

  app.use('/api/health', healthRouter);
  app.use('/api/auth', authRouter);
  app.use('/api/seasons', seasonsRouter);
  app.use('/api/season-lifecycle', seasonLifecycleRouter);
  app.use('/api/season-ops', seasonOperationsConsistencyRouter);
  app.use('/api/season-ops', seasonOperationsRouter);
  app.use('/api/leagues', leaguesRouter);
  app.use('/api/clubs', clubsRouter);
  app.use('/api/competitions', competitionConsistencyRouter);
  app.use('/api/competitions', competitionsRouter);
  app.use('/api/fixtures', fixturesRouter);
  app.use('/api/me', notificationsReadResilientRouter);
  app.use('/api/me', meRouter);
  app.use('/api/users', usersRouter);
  app.use('/api/insights', seasonInsightsRouter);
  app.use('/api/admin/image-exports', adminImageExportsRouter);
  app.use('/api/admin/cups', adminCupDrawRouter);
  app.use('/api/admin/season-lifecycle', adminSeasonLifecycleRouter);
  app.use('/api/admin/season-ops', adminSeasonOperationsRouter);
  app.use('/api/admin', adminCupOpsRouter);
  app.use('/api/admin', adminMatchControlRouter);
  app.use('/api/admin', adminConsistencyRouter);
  app.use('/api/admin', adminRouter);
  app.use('/api/admin/telegram-ai', adminAiConfigRouter);
  app.use('/api/telegram', telegramRouter);
  app.use('/api/premium', premiumPrivateRouter);
  app.use('/api/custom-tournaments/tickets', customTournamentTicketsRouter);
  app.use('/api/admin/custom-tournaments/tickets', customTournamentTicketsRouter);
  app.use('/api/custom-tournaments', customTournamentsRouter);

  app.use('/api/*', (req, res) => { res.status(404).json({ error: 'Endpoint not found', path: req.originalUrl }); });
  app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => { console.error('[SERVER] Unhandled error:', err); res.status(err.status || 500).json({ error: err.message || 'Internal Server Error', status: err.status || 500 }); });
  return app;
}

export const app = createApp();
export default app;
